import{_ as s,o as a,c as e,ag as i}from"./chunks/framework.C9sp7nFj.js";const c=JSON.parse('{"title":"SetRtToErr 输出报警停机","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/5. 设置指令/SetRtToErr.md","filePath":"3. 指令/5. 设置指令/SetRtToErr.md","lastUpdated":1778862643000}'),r={name:"3. 指令/5. 设置指令/SetRtToErr.md"};function n(l,t,o,h,d,p){return a(),e("div",null,[...t[0]||(t[0]=[i(`<h1 id="setrttoerr-输出报警停机" tabindex="-1">SetRtToErr 输出报警停机 <a class="header-anchor" href="#setrttoerr-输出报警停机" aria-label="Permalink to &quot;SetRtToErr 输出报警停机&quot;">​</a></h1><p>该指令用于<strong>强制终止机器人当前程序的运行，并向系统发出自定义的报警信息</strong>。它是程序逻辑中处理异常、安全联锁或工艺错误的核心手段。执行此指令后，机器人会进入停止状态，示教器及监控系统会弹出指定的错误编号和文字提示。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>SetRtToErr(msg, errId) SetRtToErr(错误信息, 错误编号)</p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>msg：错误信息（errInfo）</td><td>str / STRING 变量</td><td>显示在报错界面的文字描述。用于告知操作人员具体的错误原因（如&quot;真空吸取失败&quot;、&quot;安全门打开&quot;等）。</td><td></td></tr><tr><td>errId：错误编号（errId）</td><td>int / INT 变量</td><td>系统分配给该错误的唯一 ID。</td><td>取值范围：<strong>90001 - 100000</strong>（该范围通常预留给用户自定义报警，避免与系统原生错误码冲突）。</td></tr></tbody></table><hr><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><p>当程序运行到该指令时，系统会执行以下操作：</p><ol><li><strong>立即停止</strong>：机器人各轴减速停止，切断运动使能。</li><li><strong>状态记录</strong>：将 <code>errId</code> 和 <code>msg</code> 记录到系统报警日志中。</li><li><strong>交互提示</strong>：在示教器弹出窗口，必须由操作员人工确认（Reset/Clear）后方可重新启动。</li></ol><hr><h2 id="示例-异常处理逻辑" tabindex="-1">示例：异常处理逻辑 <a class="header-anchor" href="#示例-异常处理逻辑" aria-label="Permalink to &quot;示例：异常处理逻辑&quot;">​</a></h2><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 检查夹爪状态信号 DI1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">IF</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (DI1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> OFF</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">THEN</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    SetRtToErr</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;工件掉落：请检查夹爪&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">90005</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ENDIF</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><strong>执行结果：</strong></p><p>如果 <strong>DI1</strong> 信号为断开状态（工件未抓稳），机器人会立刻停机，屏幕显示：<code>[90005] 工件掉落：请检查夹爪</code>。</p><hr><h2 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to &quot;应用场景&quot;">​</a></h2><ul><li><strong>安全联锁</strong>：在执行关键动作前，检查安全栅栏、光幕信号，若不满足则报错停机。</li><li><strong>工艺自检</strong>：配合 <code>WaitCondition</code> 或 <code>IF</code> 语句，当工件位姿不准、气压不足或视觉识别失败时发出警报。</li><li><strong>流程防错</strong>：在多工序衔接中，如果上道工序未完成，防止机器人进入加工区域造成碰撞。</li></ul>`,19)])])}const g=s(r,[["render",n]]);export{c as __pageData,g as default};
